import { cn } from '@/utils/cn';
import { cva, VariantProps } from 'class-variance-authority';
import { Component, createEffect, createUniqueId, mergeProps, splitProps } from 'solid-js';

type CheckboxBaseProps = {
  id?: string;
  name?: string;
  indeterminate?: boolean;
  class?: string;
  size?: CheckboxVariantsProps['size'];
  color?: CheckboxVariantsProps['color'];
  disabled?: boolean;
  onChange?: (checked: boolean) => void;
  value?: string;
};

type CheckboxUncontrolled = CheckboxBaseProps & {
  defaultChecked?: boolean;
  checked?: never;
};

type CheckboxControlled = CheckboxBaseProps & {
  checked: boolean;
  defaultChecked?: never;
};

export type CheckboxProps = CheckboxUncontrolled | CheckboxControlled;

const variants = cva('checkbox', {
  variants: {
    size: {
      xs: 'checkbox-xs',
      sm: 'checkbox-sm',
      md: 'checkbox-md',
      lg: 'checkbox-lg',
      xl: 'checkbox-xl',
    },
    color: {
      default: '',
      neutral: 'checkbox-neutral',
      primary: 'checkbox-primary',
      secondary: 'checkbox-secondary',
      accent: 'checkbox-accent',
      info: 'checkbox-info',
      success: 'checkbox-success',
      warning: 'checkbox-warning',
      error: 'checkbox-error',
    },
  },
});

export type CheckboxVariantsProps = VariantProps<typeof variants>;

export const Checkbox: Component<CheckboxProps> = props => {
  const merged = mergeProps(
    { size: 'xs', color: 'primary', id: createUniqueId() } as CheckboxProps,
    props,
  );
  const [p, _] = splitProps(merged, [
    'id',
    'name',
    'indeterminate',
    'class',
    'size',
    'color',
    'disabled',
    'onChange',
    'value',
    'checked',
    'defaultChecked',
  ]);

  let inputRef: HTMLInputElement | undefined;

  createEffect(function syncIndeterminate() {
    if (!inputRef) return;
    inputRef.indeterminate = !!p.indeterminate;
  });

  return (
    <input
      ref={el => {
        inputRef = el;
        if (p.defaultChecked !== undefined) el.checked = p.defaultChecked;
      }}
      type="checkbox"
      id={p.id}
      class={cn(variants({ size: p.size, color: p.color }), p.class)}
      disabled={p.disabled}
      {...(p.name && { name: p.name })}
      {...(p.indeterminate && { 'data-indeterminate': true })}
      {...(p.checked !== undefined && { checked: p.checked })}
      onClick={e => {
        if (p.indeterminate || p.disabled) e.preventDefault();
      }}
      onChange={e => p.onChange?.(e.target.checked)}
      value={p.value}
    />
  );
};
